package world.hachimi.app.util

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.jetbrains.compose.resources.StringResource
import org.jetbrains.compose.resources.getString
import world.hachimi.app.getPlatform

/**
 * Resolves a [StringResource] on the main thread.
 *
 * Reading a string also reads the platform resource environment (language, region, dark theme and
 * density). On OHOS that environment is queried from ArkTS over N-API, and N-API calls are only
 * valid on the JS/UI thread. Resolving a string from a worker dispatcher therefore aborts the
 * process with `ecma_vm cannot run in multi-thread!`.
 *
 * Use this instead of [getString] whenever the caller may run off the main thread.
 */
suspend fun getStringOnMain(resource: StringResource, vararg formatArgs: Any): String =
    if (getPlatform().name == "ohos") {
        withContext(Dispatchers.Main) { getString(resource, *formatArgs) }
    } else {
        // Other platforms resolve the environment without crossing into a UI toolkit.
        getString(resource, *formatArgs)
    }

rootProject.name = "HachimiWorld"
enableFeaturePreview("TYPESAFE_PROJECT_ACCESSORS")

// This branch only builds the OHOS target, so the CPF-published Kotlin/Compose artifacts are the
// only ones needed. Upstream's own version matrix stays in gradle/libs.versions.toml for reference
// (see OHOS_MIGRATION.md) but is not used.
pluginManagement {
    repositories {
        mavenLocal()
        maven("https://maven.eazytec-cloud.com/nexus/repository/maven-public/")
        google {
            mavenContent {
                includeGroupAndSubgroups("androidx")
                includeGroupAndSubgroups("com.android")
                includeGroupAndSubgroups("com.google")
            }
        }
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    defaultLibrariesExtensionName = "upstreamLibs"
    versionCatalogs {
        create("libs") { from(files("gradle/ohos.versions.toml")) }
    }
    repositories {
        mavenLocal()
        maven("https://maven.eazytec-cloud.com/nexus/repository/maven-public/")
        google {
            mavenContent {
                includeGroupAndSubgroups("androidx")
                includeGroupAndSubgroups("com.android")
                includeGroupAndSubgroups("com.google")
            }
        }
        mavenCentral()
    }
}

plugins {
    id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0"
}

// Only the shared module is built here; the runnable app is the HarmonyOS project in harmonyApp/.
// build.ohos.gradle.kts replaces build.gradle.kts because upstream (Kotlin 2.3.21 / Compose 1.11.1)
// and CPF (2.2.21-1.0.0 / 1.9.2-1.0.0) cannot share one build script. The upstream
// composeApp/build.gradle.kts is left untouched as a reference for the next upstream rebase.
include(":composeApp")
rootProject.buildFileName = "build.ohos.gradle.kts"
project(":composeApp").buildFileName = "build.ohos.gradle.kts"

#include "libkn_api.h"
#include "napi/native_api.h"
#include "hilog/log.h"
#include <rawfile/raw_file_manager.h>
#include <dlfcn.h>

// 避免工程侧未定义 LOG_DOMAIN 时编译失败
#ifndef LOG_DOMAIN
#define LOG_DOMAIN 0x0000
#endif

static napi_value MainArkUIViewController(napi_env env, napi_callback_info info) {
    return reinterpret_cast<napi_value>(MainArkUIViewController(env));
}

extern "C" void* HachimiInitPlatform(void* env, void* info);
extern "C" void* HachimiDisposePlatform(void* env, void* info);

static napi_value InitPlatform(napi_env env, napi_callback_info info) {
    return reinterpret_cast<napi_value>(HachimiInitPlatform(env, info));
}

static napi_value DisposePlatform(napi_env env, napi_callback_info info) {
    return reinterpret_cast<napi_value>(HachimiDisposePlatform(env, info));
}

EXTERN_C_START
static napi_value Init(napi_env env, napi_value exports) {
    androidx_compose_ui_arkui_init(env, exports);
    napi_property_descriptor desc[] = {
        {"initPlatform", nullptr, InitPlatform, nullptr, nullptr, nullptr, napi_default, nullptr},
        {"disposePlatform", nullptr, DisposePlatform, nullptr, nullptr, nullptr, napi_default, nullptr},
        {"MainArkUIViewController", nullptr, MainArkUIViewController, nullptr, nullptr, nullptr, napi_default, nullptr},
    };
    napi_define_properties(env, exports, sizeof(desc) / sizeof(desc[0]), desc);
    return exports;
}
EXTERN_C_END

static napi_module demoModule = {
    .nm_version = 1,
    .nm_flags = 0,
    .nm_filename = nullptr,
    .nm_register_func = Init,
    .nm_modname = "entry",
    .nm_priv = ((void*)0),
    .reserved = { 0 },
};

extern "C" __attribute__((constructor)) void RegisterEntryModule(void)
{
    napi_module_register(&demoModule);
}
